realWorldExample:
In production frontend applications, Promises power network communication (Fetch API), cached resource pipelines, and resilient state synchronization.

Example: Implementing an exponential-backoff resilient API fetcher with AbortController timeout:

async function fetchWithRetry(url, { maxRetries = 3, timeoutMs = 5000, delayMs = 1000 } = {}) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetch(url, { signal: controller.signal });
      clearTimeout(timeoutId);
      if (!response.ok) throw new Error(`HTTP Error ${response.status}`);
      return await response.json();
    } catch (err) {
      clearTimeout(timeoutId);
      if (attempt === maxRetries) throw err;
      await new Promise(r => setTimeout(r, delayMs * Math.pow(2, attempt - 1)));
    }
  }
}

