// Comprehensive Demonstration: ES6 Promise States, A+ Spec Chaining & Microtask Scheduling
function demonstratePromiseLifecycle() {
  console.log('1: Synchronous script starts');

  // 1. Initial State: Pending
  const promise = new Promise((resolve, reject) => {
    console.log('2: Promise executor runs synchronously');

    setTimeout(() => {
      // 2. Transition: Pending -> Fulfilled (Immutable)
      resolve('Success Payload');
      // Subsequent transitions are ignored by A+ specification guarantee
      reject(new Error('Ignored rejection after fulfillment'));
    }, 100);
  });

  console.log('3: Promise object constructed (State: Pending)');

  // 3. A+ Chaining and Microtask Dispatch
  promise
    .then((result) => {
      console.log('4: onFulfilled triggered in microtask with:', result);
      // Returning a value fulfills the chained promise with that value
      return result.toUpperCase();
    })
    .then((transformed) => {
      console.log('5: Chained onFulfilled received:', transformed);
      // Throwing an error transitions chained promise to Rejected
      throw new Error('Downstream processing failed');
    })
    .catch((error) => {
      console.log('6: onRejected caught error:', error.message);
      // Returning from catch recovers the chain back to Fulfilled
      return 'Fallback Default Value';
    })
    .finally(() => {
      console.log('7: finally handler runs regardless of outcome');
    });

  console.log('8: Synchronous script finishes');
}

demonstratePromiseLifecycle();

